#include <cstddef>
#include <cstdint>
namespace{constexpr std::size_t max_words=32,max_word_len=8,max_input=307;bool eq(const std::int64_t*v,std::size_t s,std::size_t n,std::size_t t,std::size_t m){if(n!=m)return false;for(std::size_t i=0;i<n;++i)if(v[s+i]!=v[t+i])return false;return true;}}
extern "C" std::int64_t shortest_word_distance(const std::int64_t*v,std::size_t length){if(v==nullptr||length<1||length>max_input+1||v[0]<2||v[0]>32)return -1;const auto n=static_cast<std::size_t>(v[0]);std::size_t starts[32],sizes[32],p=1;for(std::size_t i=0;i<n;++i){if(p>=length)return -1;const auto z=v[p++];if(z<1||z>8||p+static_cast<std::size_t>(z)>length)return -1;starts[i]=p;sizes[i]=static_cast<std::size_t>(z);for(std::size_t j=0;j<sizes[i];++j)if(!((v[p+j]>=65&&v[p+j]<=90)||(v[p+j]>=97&&v[p+j]<=122)))return -1;p+=sizes[i];}std::size_t ts[2],tn[2];for(std::size_t t=0;t<2;++t){if(p>=length)return -1;const auto z=v[p++];if(z<1||z>8||p+static_cast<std::size_t>(z)>length)return -1;ts[t]=p;tn[t]=static_cast<std::size_t>(z);for(std::size_t j=0;j<tn[t];++j)if(!((v[p+j]>=65&&v[p+j]<=90)||(v[p+j]>=97&&v[p+j]<=122)))return -1;p+=tn[t];}if(p!=length||eq(v,ts[0],tn[0],ts[1],tn[1]))return -1;bool h0=false,h1=false;std::size_t best=n;for(std::size_t i=0;i<n;++i){const bool a=eq(v,starts[i],sizes[i],ts[0],tn[0]),b=eq(v,starts[i],sizes[i],ts[1],tn[1]);h0|=a;h1|=b;for(std::size_t j=0;j<n;++j){const bool c=eq(v,starts[j],sizes[j],ts[0],tn[0]),d=eq(v,starts[j],sizes[j],ts[1],tn[1]);if((a&&d)||(b&&c)){const auto delta=i>j?i-j:j-i;if(delta<best)best=delta;}}}return h0&&h1?static_cast<std::int64_t>(best):-1;}
